add_filter('woocommerce_registration_errors', function ($errors, $username, $email) {
    $req = [
        'first_name'    => 'Nombre',
        'last_name'     => 'Apellidos',
        'billing_phone' => 'Teléfono',
    ];
    foreach ($req as $key => $label) {
        if (empty($_POST[$key])) {
            $errors->add("required_{$key}", sprintf('<strong>Error</strong>: %s es obligatorio.', esc_html($label)));
        }
    }
    if (empty($_POST['privacy_accept'])) {
        $errors->add('required_privacy', '<strong>Error</strong>: Debes aceptar la política de privacidad.');
    }
    return $errors;
}, 10, 3);

/* SNIPPET 3: Guardado de meta en el usuario al registrarse */
add_action('woocommerce_created_customer', function ($customer_id) {
    // Nombre y apellidos (perfil WP)
    if (isset($_POST['first_name'])) {
        update_user_meta($customer_id, 'first_name', sanitize_text_field(wp_unslash($_POST['first_name'])));
    }
    if (isset($_POST['last_name'])) {
        update_user_meta($customer_id, 'last_name', sanitize_text_field(wp_unslash($_POST['last_name'])));
    }

    // Metadatos útiles
    $map = [
        'billing_phone'   => 'billing_phone',
        'billing_company' => 'billing_company',
        'billing_city'    => 'billing_city',
        'industry'        => 'industry',
        'lead_source'     => 'lead_source',
    ];
    foreach ($map as $postKey => $metaKey) {
        if (isset($_POST[$postKey])) {
            update_user_meta($customer_id, $metaKey, sanitize_text_field(wp_unslash($_POST[$postKey])));
        }
    }
});

